const BOOKED_STAFF_ALLOCATED = 'appointment booked - staff allocated';

function normStatus(status) {
  const s = normHeader(status).replace(/[–—−]/g, '-').replace(/\s*-\s*/g, ' - ');
  return s;
}

function rowsFrom(name) {
  try { return $(name).all().map((i) => i.json || {}); } catch (e) { return []; }
}

function probeRow(rows) {
  const probe = {};
  for (const row of rows) {
    if (!row) continue;
    for (const k of Object.keys(row)) {
      if (!(k in probe)) probe[k] = row[k];
    }
  }
  return probe;
}

function normHeader(h) {
  return String(h ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function pickCol(row, aliases) {
  const keys = Object.keys(row || {});
  const normed = keys.map((k) => ({ k, n: normHeader(k) }));
  for (const alias of aliases) {
    const a = normHeader(alias);
    for (const item of normed) {
      if (item.n === a) return item.k;
    }
  }
  for (const alias of aliases) {
    const a = normHeader(alias);
    for (const item of normed) {
      if (item.n.includes(a)) return item.k;
    }
  }
  return null;
}

function normCorf(v) {
  return String(v ?? '').trim().toUpperCase().replace(/\s+/g, '');
}

function parseDate(v) {
  if (v === null || v === undefined || v === '') return null;
  if (v instanceof Date && !isNaN(v)) return v.toISOString().slice(0, 10);
  if (typeof v === 'number' && isFinite(v)) {
    const epoch = Date.UTC(1899, 11, 30);
    const ms = epoch + v * 86400000;
    return new Date(ms).toISOString().slice(0, 10);
  }
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  m = s.match(/^(\d{1,2})-(\d{1,2})-(\d{4})/);
  if (m) return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`;
  return null;
}

function londonTodayIso() {
  const fmt = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'Europe/London',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  });
  const parts = fmt.formatToParts(new Date());
  const m = {};
  for (let i = 0; i < parts.length; i++) {
    if (parts[i].type !== 'literal') m[parts[i].type] = parts[i].value;
  }
  return `${m.year}-${m.month}-${m.day}`;
}

function statusActive(status) {
  return normStatus(status) === BOOKED_STAFF_ALLOCATED;
}

function isCompleted(v) {
  const s = String(v ?? '').trim().toLowerCase();
  return ['yes', 'y', 'true', '1', 'completed'].includes(s);
}

function cell(row, colKey) {
  if (!colKey) return '';
  if (!Object.prototype.hasOwnProperty.call(row || {}, colKey)) return '';
  const v = row[colKey];
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

function readDateCell(row, colKey) {
  if (!colKey || !Object.prototype.hasOwnProperty.call(row || {}, colKey)) return { raw: '', iso: null };
  const v = row[colKey];
  if (v === null || v === undefined || v === '') return { raw: '', iso: null };
  const iso = parseDate(v);
  const raw = iso || String(v).trim();
  return { raw, iso };
}

function pickNextFromSchedDates(dates, asOf, currentIso) {
  const sorted = dates.slice().sort();
  const future = sorted.filter((d) => d >= asOf);
  if (future.length) return future[0];
  if (currentIso) {
    const newer = sorted.filter((d) => d > currentIso);
    if (newer.length) return newer[0];
  }
  return null;
}

const schedRows = rowsFrom('Read scheduling xlsx');
const wiRows = rowsFrom('Read works list xlsx');
const asOf = londonTodayIso();

const schedProbe = probeRow(schedRows);
const wiProbe = probeRow(wiRows);

const schedCorfCol = pickCol(schedProbe, ['client order reference', 'client reference', 'corf', 'client order ref']);
const schedDateCol = pickCol(schedProbe, ['appointment date', 'appointment date/time', 'appointment date and time', 'date']);
const schedStatusCol = pickCol(schedProbe, ['appointment status', 'status', 'scheduling status']);

const wiCorfCol = pickCol(wiProbe, ['client order reference']);
const wiNextCol = pickCol(wiProbe, ['next appointment date']);
const wiDoneCol = pickCol(wiProbe, ['completed']);
const wiAddrCol = pickCol(wiProbe, ['address']);
const wiDescCol = pickCol(wiProbe, ['description of work']);

const schedDatesByCorf = new Map();
let bookedRowsKept = 0;
let startedRowsSkipped = 0;
let otherStatusSkipped = 0;
for (const row of schedRows) {
  const corf = normCorf(cell(row, schedCorfCol));
  if (!corf) continue;
  const status = cell(row, schedStatusCol);
  if (!statusActive(status)) {
    const ns = normStatus(status);
    if (ns === 'appointment started') startedRowsSkipped += 1;
    else otherStatusSkipped += 1;
    continue;
  }
  bookedRowsKept += 1;
  const d = parseDate(row[schedDateCol]);
  if (!d) continue;
  const list = schedDatesByCorf.get(corf) || [];
  list.push(d);
  schedDatesByCorf.set(corf, list);
}

const needsUpdate = [];
let alreadyOk = 0;
let noFuture = 0;
let skippedCompleted = 0;

for (const row of wiRows) {
  const corfRaw = cell(row, wiCorfCol);
  const corf = normCorf(corfRaw);
  if (!corf) continue;
  if (isCompleted(cell(row, wiDoneCol))) { skippedCompleted++; continue; }

  const { raw: currentRaw, iso: current } = readDateCell(row, wiNextCol);
  const dates = schedDatesByCorf.get(corf) || [];
  const next = pickNextFromSchedDates(dates, asOf, current);

  if (!next) {
    noFuture++;
    continue;
  }
  if (current === next) {
    alreadyOk++;
    continue;
  }

  needsUpdate.push({
    client_order_reference: corfRaw,
    address: cell(row, wiAddrCol),
    description_of_work: cell(row, wiDescCol),
    current_next_appointment_date: current || currentRaw || null,
    computed_next_appointment_date: next,
    action: 'update',
  });
}

const seenCorf = new Set();
const deduped = [];
for (const row of needsUpdate) {
  const key = normCorf(row.client_order_reference);
  if (!key || seenCorf.has(key)) continue;
  seenCorf.add(key);
  deduped.push(row);
}

const sd = $getWorkflowStaticData('global');
sd.nextApptLogs = [];
sd.nextApptCompare = {
  as_of: asOf,
  as_of_timezone: 'Europe/London',
  scheduling_rows: schedRows.length,
  works_list_rows: wiRows.length,
  wi_next_col: wiNextCol,
  wi_column_count: Object.keys(wiProbe).length,
  status_filter: BOOKED_STAFF_ALLOCATED,
  sched_status_column: schedStatusCol,
  booked_rows_kept: bookedRowsKept,
  started_rows_skipped: startedRowsSkipped,
  other_status_skipped: otherStatusSkipped,
  scheduling_jobs_with_booked_staff: schedDatesByCorf.size,
  needs_update_count: deduped.length,
  needs_update_raw_count: needsUpdate.length,
  already_correct_count: alreadyOk,
  no_future_in_register_count: noFuture,
  skipped_completed: skippedCompleted,
};

if (!deduped.length) {
  return [{
    json: {
      _workflow_only: true,
      _no_jobs: true,
      message: `Compare done — 0 jobs need update (already_ok=${alreadyOk}, no_future=${noFuture})`,
      ...sd.nextApptCompare,
    },
  }];
}

return deduped.map((row, i) => ({ json: { ...row, _job_index: i + 1, _job_total: deduped.length } }));

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && body.body && body.works_id === undefined && body.results === undefined) {
    body = body.body;
  }
  return body || {};
}

const resp = $input.first().json || {};
const resolve = bodyFrom(resp);
const job = $('Loop update jobs').item.json || {};

return [{
  json: {
    ...job,
    works_id: String(resolve.works_id || '').trim(),
    resolve_found: Boolean(resolve.found),
    resolve_address: resolve.address || '',
    resolve_error: resolve.error || null,
    resolve_message: resolve.message || '',
  },
}];

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && body.body && body.success === undefined && body.works_id === undefined) {
    body = body.body;
  }
  return body || {};
}

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.nextApptLogs)) sd.nextApptLogs = [];

const job = $('Loop update jobs').item.json || {};
const parsed = $('Parse resolve response').first().json || {};

let update = {};
let step = 'resolve_failed';
try {
  const raw = $('Update next appointment').first().json || {};
  update = bodyFrom(raw);
  if (update && (update.success !== undefined || update.works_id)) step = 'updated';
} catch (e) {}

if (parsed.resolve_found && parsed.works_id) step = step === 'updated' ? 'updated' : step;

const entry = {
  step,
  job_index: job._job_index || null,
  job_total: job._job_total || null,
  client_order_reference: job.client_order_reference || parsed.client_order_reference || '',
  works_id: parsed.works_id || job.works_id || '',
  address: job.address || parsed.resolve_address || '',
  current_next_appointment_date: job.current_next_appointment_date || null,
  computed_next_appointment_date: job.computed_next_appointment_date || null,
  resolve_found: Boolean(parsed.resolve_found),
  resolve_error: parsed.resolve_error || null,
  update_success: update.success === true && update.saved === true,
  update_error: update.error || null,
  field_value_after: update.field_value_verified || update.field_value_after || null,
  url: update.url || null,
  message: update.message || parsed.resolve_message || parsed.resolve_error || 'skipped — works_id not found',
  logged_at: new Date().toISOString(),
};

sd.nextApptLogs.push(entry);
return [{ json: entry }];

const sd = $getWorkflowStaticData('global');
const logs = Array.isArray(sd.nextApptLogs) ? sd.nextApptLogs : [];
const compare = sd.nextApptCompare || {};

const updated = logs.filter((l) => l.step === 'updated' && l.update_success).length;
const resolveFailed = logs.filter((l) => l.step === 'resolve_failed').length;
const updateFailed = logs.filter((l) => l.step === 'updated' && !l.update_success).length;

const lines = logs.map((l) => {
  const corf = l.client_order_reference || '-';
  const wid = l.works_id || '-';
  if (l.step === 'resolve_failed') {
    return `SKIP resolve corf=${corf} — ${l.message}`;
  }
  return `${l.update_success ? 'OK' : 'FAIL'} [${l.job_index || '?'}/${l.job_total || '?'}] corf=${corf} works_id=${wid} ${l.current_next_appointment_date || '(blank)'} -> ${l.computed_next_appointment_date} field=${l.field_value_after || '-'} ${l.message || ''}`;
});

return [{
  json: {
    _workflow_only: true,
    workflow: 'next_appointment_cleanse',
    finished_at: new Date().toISOString(),
    compare,
    processed: logs.length,
    updated_ok: updated,
    resolve_failed: resolveFailed,
    update_failed: updateFailed,
    log_lines: lines,
    message: `Next appointment cleanse done — updated ${updated}/${logs.length} (resolve_failed=${resolveFailed}, update_failed=${updateFailed})`,
  },
}];

function esc(t) {
  return String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const sd = $getWorkflowStaticData('global');
const logs = Array.isArray(sd.nextApptLogs) ? sd.nextApptLogs : [];

const reportDate = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London' }).replace(',', '');
const logo = 'https://jeffway.co.uk/wp-content/uploads/2025/05/jeffway-group-1.svg';

const updatedOk = logs.filter((l) => l.step === 'updated' && l.update_success).length;
const resolveFailed = logs.filter((l) => l.step === 'resolve_failed').length;
const updateFailed = logs.filter((l) => l.step === 'updated' && !l.update_success).length;
const processed = logs.length;

function statusLabel(l) {
  if (l.step === 'resolve_failed') return { text: 'Resolve failed', color: '#b45309' };
  if (l.update_success) return { text: 'Updated', color: '#15803d' };
  return { text: 'Update failed', color: '#b91c1c' };
}

let jobRows = '';
if (logs.length) {
  jobRows = logs.map((l) => {
    const st = statusLabel(l);
    return '<tr>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.job_index || '-') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.client_order_reference || '-') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.address || '-') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.works_id || '-') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.current_next_appointment_date || '(blank)') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.computed_next_appointment_date || '-') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.field_value_after || l.field_value_verified || '-') + '</td>'
      + '<td style="padding:8px;border-bottom:1px solid #eee;color:' + st.color + ';font-weight:bold;">' + esc(st.text) + '</td>'
      + '</tr>';
  }).join('');
} else {
  jobRows = '<tr><td colspan="8" style="padding:16px;text-align:center;color:#666;">No updates this run.</td></tr>';
}

const html = [
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>',
  '<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f4f4f4;">',
  '<table width="100%" style="background:#f4f4f4;padding:20px;"><tr><td align="center">',
  '<table width="760" style="background:#fff;border-radius:8px;overflow:hidden;">',
  '<tr><td style="background:#000;padding:20px;text-align:center;"><img src="' + logo + '" style="max-width:160px;" alt="Jeffway"></td></tr>',
  '<tr><td style="padding:20px 24px 8px;"><h2 style="margin:0;color:#111;">Stage 6 — Next Appointment Cleanse</h2>',
  '<p style="color:#777;font-size:13px;margin:8px 0 0;">' + esc(reportDate) + ' (Europe/London)</p></td></tr>',
  '<tr><td style="padding:8px 24px 24px;">',
  '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:12px;">',
  '<tr style="background:#f3f3f3;">',
  '<th align="left" style="padding:8px;">#</th>',
  '<th align="left" style="padding:8px;">CORF</th>',
  '<th align="left" style="padding:8px;">Address</th>',
  '<th align="left" style="padding:8px;">Works ID</th>',
  '<th align="left" style="padding:8px;">Current</th>',
  '<th align="left" style="padding:8px;">New</th>',
  '<th align="left" style="padding:8px;">Field after</th>',
  '<th align="left" style="padding:8px;">Status</th>',
  '</tr>',
  jobRows,
  '</table></td></tr>',
  '<tr><td style="background:#f9f9f9;padding:16px;text-align:center;font-size:12px;color:#777;">Jeffway Group · Automated Next appointment cleanse</td></tr>',
  '</table></td></tr></table></body></html>',
].join('');

return [{
  json: {
    _alert_subject: 'Stage 6 Next Appointment Cleanse — ' + reportDate + (processed ? (' — ' + updatedOk + '/' + processed + ' updated') : ' — no updates'),
    _alert_html: html,
    processed,
    updated_ok: updatedOk,
    resolve_failed: resolveFailed,
    update_failed: updateFailed,
  },
}];
